SourceCode.Declaration:
/// <summary>
/// Parameter data contract for importing files from Azure file shares
/// </summary>
[DataContract]
class OMGInboundDataContract_AzureFileShare extends OMGInboundDataContract_Azure
{        
    OMGFileShareName            fileShareName;
    OMGFileShareDirectory       archiveDirectory;             
    OMGFileShareDirectory       sourceDirectory;   

}

Method.Source:
[DataMember, OMGAzureFileShareName, SysOperationDisplayOrder('3')]
public OMGFileShareName parmFileShareName(OMGFileShareName _fileShareName = fileShareName)
{
    fileShareName = _fileShareName;
    return fileShareName;
}

[DataMember, SysOperationLabel(literalStr("@OMG:AzureSourceDirectory")), OMGAzureFileShareDirectory, SysOperationDisplayOrder('4')]
public OMGFileShareDirectory parmSourceDirectory(OMGFileShareDirectory _sourceDirectory = sourceDirectory)
{
    sourceDirectory = _sourceDirectory;
    return sourceDirectory;
}

[DataMember, SysOperationLabel(literalStr("@OMG:AzureArchiveDirectory")), OMGAzureFileShareDirectory, OMGArchiveDirectory, SysOperationDisplayOrder('5')]
public OMGFileShareDirectory parmArchiveDirectory(OMGFileShareDirectory _archiveDirectory = archiveDirectory)
{
    archiveDirectory = _archiveDirectory;
    return archiveDirectory;
}

/// <summary>
/// The caption used on the dialog
/// </summary>
/// <returns>A descriptive text</returns>
public Description dialogCaption()
{
    return "@OMG:ImportFilesFromAzureFileShare";
}
